nta.declaration:
const int NUM_ENEMIES = 2;           
const int TIMEOUT = 50;              
const int MAX_PATH_LENGTH = 22;      

const int CIRCLE_SPEED  = 1;         
const int CIRCLE_HEALTH = 10;        
const int CIRCLE_DAMAGE = 2;         
const int SQUARE_SPEED  = 3;         
const int SQUARE_HEALTH = 20;        
const int SQUARE_DAMAGE = 4;         

const int spawn_times[NUM_ENEMIES] = {0, 2};
const int MAIN_TOWER_HEALTH = 10;
int lives = MAIN_TOWER_HEALTH;

int global_clock = 0;             
bool game_over = false;           
bool timeout_reached = false;     

int enemy_health[NUM_ENEMIES];        
int enemy_damage[NUM_ENEMIES];        
int enemy_position[NUM_ENEMIES];      
int enemy_spawn_time[NUM_ENEMIES];    
bool enemy_spawned[NUM_ENEMIES];      
bool enemy_alive[NUM_ENEMIES];        
int enemy_move_counter[NUM_ENEMIES];  

broadcast chan clock_tick;

void init_game() {
    int i;
    lives = MAIN_TOWER_HEALTH;
    global_clock = 0;
    game_over = false;
    timeout_reached = false;

    for (i = 0; i < NUM_ENEMIES; i++) {
        if (i == 0) {
            enemy_health[i] = CIRCLE_HEALTH;
            enemy_damage[i] = CIRCLE_DAMAGE;
        } else {
            enemy_health[i] = SQUARE_HEALTH;
            enemy_damage[i] = SQUARE_DAMAGE;
        }

        enemy_spawn_time[i]     = spawn_times[i];
        enemy_position[i]       = -1;  
        enemy_spawned[i]        = false;
        enemy_alive[i]          = true;
        enemy_move_counter[i]   = 0;
    }
}

int get_enemy_speed(int i) {
    if (i == 0) return CIRCLE_SPEED;
    else        return SQUARE_SPEED;
}

bool can_move_forward(int i) {
    return enemy_alive[i] && 
           enemy_spawned[i] && 
           enemy_position[i] >= 0 && 
           enemy_position[i] < MAX_PATH_LENGTH &&
           enemy_health[i] > 0;
}

bool enemy_reached_goal(int i) {
    return enemy_alive[i] && 
           enemy_spawned[i] && 
           enemy_position[i] >= MAX_PATH_LENGTH;
}

void move_enemy_forward(int i) {
    if (can_move_forward(i)) {
        enemy_position[i] = enemy_position[i] + 1;
    }
}

void remove_enemy_from_map(int i) {
    enemy_position[i] = -1;
    enemy_spawned[i] = false;
    enemy_alive[i] = false;
}

bool all_enemies_gone() {
    int i;
    for (i = 0; i < NUM_ENEMIES; i++) {
        if (enemy_spawned[i] && enemy_alive[i] && enemy_position[i] >= 0) {
            return false;
        }
    }
    return true;
}

bool enemy_on_valid_path(int i) {
    if (!enemy_spawned[i] || !enemy_alive[i]) {
        return true;
    }
    return (enemy_position[i] >= 0 && enemy_position[i] <= MAX_PATH_LENGTH);
}

nta.system:
// Initialize game state
init_game();

// Instantiate system components
clock = GameClock();
gameManager = GameManager();

// Create 2 enemies for faster verification
enemy0 = Enemy(0);  // Circle
enemy1 = Enemy(1);  // Square

// System composition
system clock, gameManager, enemy0, enemy1;
